CREATE TABLE `workspaces` (`id` text PRIMARY KEY NOT NULL, `session_id` text NOT NULL UNIQUE, `mode` text DEFAULT 'demo' NOT NULL, `created_at` text NOT NULL);
CREATE TABLE `targets` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL REFERENCES `workspaces`(`id`) ON DELETE cascade, `school` text, `department` text, `program` text, `degree_type` text, `batch` text, `assessment_year` integer, `enrollment_year` integer, `mentor_name` text, `mentor_homepage` text);
CREATE TABLE `sources` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL REFERENCES `workspaces`(`id`) ON DELETE cascade, `title` text NOT NULL, `url` text, `author` text, `published_at` text, `fetched_at` text NOT NULL, `stated_year` text, `scope` text, `source_type` text NOT NULL, `access_status` text NOT NULL, `content_range` text, `content_hash` text NOT NULL, `reprint_of` text, `visibility` text DEFAULT 'private' NOT NULL, `content` text NOT NULL);
CREATE TABLE `evidences` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL REFERENCES `workspaces`(`id`) ON DELETE cascade, `source_id` text NOT NULL REFERENCES `sources`(`id`) ON DELETE cascade, `quote` text NOT NULL, `locator` text NOT NULL, `located` integer NOT NULL, `search_snippet_only` integer DEFAULT false NOT NULL);
CREATE TABLE `claims` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL REFERENCES `workspaces`(`id`) ON DELETE cascade, `content` text NOT NULL, `claim_type` text NOT NULL, `evidence_ids` text NOT NULL, `scope` text NOT NULL, `verification` text NOT NULL, `conflict_ids` text DEFAULT '[]' NOT NULL);
CREATE TABLE `research_tasks` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL REFERENCES `workspaces`(`id`) ON DELETE cascade, `kind` text NOT NULL, `status` text NOT NULL, `search_count` integer DEFAULT 0 NOT NULL, `fetch_count` integer DEFAULT 0 NOT NULL, `detail` text, `updated_at` text NOT NULL);
CREATE TABLE `training_records` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL REFERENCES `workspaces`(`id`) ON DELETE cascade, `module` text NOT NULL, `item_id` text NOT NULL, `answer` text NOT NULL, `result_kind` text NOT NULL, `result` text NOT NULL, `feedback` text NOT NULL, `retest_of` text, `created_at` text NOT NULL);
CREATE TABLE `attachments` (`id` text PRIMARY KEY NOT NULL, `workspace_id` text NOT NULL REFERENCES `workspaces`(`id`) ON DELETE cascade, `filename` text NOT NULL, `mime_type` text NOT NULL, `size` integer NOT NULL, `storage_path` text NOT NULL, `extracted_text` text NOT NULL, `parse_status` text NOT NULL, `created_at` text NOT NULL);
